      ctx.fillStyle = '#bc8040'; ctx.beginPath(); ctx.arc(X - 1, Y - 1, 3.4, 0, 7); ctx.fill();
      ctx.fillStyle = '#f0dcb4'; ctx.fillRect(X - 3, Y - 3, 2, 2);
