      if (e.st === 'wind') { if (Math.floor(e.t / 4) % 2) flash(ctx, 'w9_gwtim_2', X, Y, e.dir > 0, 0.35); DD.text('!', Math.round(X), Math.round(Y - 44), '#ff6a58', 1, '#000', 'center'); }
